
#ifndef HAS_CUDA_ROTATE
#define HAS_CUDA_ROTATE
__device__ inline unsigned int rotate(unsigned int x, unsigned int n) {
    return (x << n) | (x >> (32 - n));
}
__device__ inline unsigned long long rotate(unsigned long long x, unsigned int n) {
    return (x << n) | (x >> (64 - n));
}
#endif


    // === SHA256 ===
    
// SHA-256 Constants
static __constant__ unsigned int K256[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
};

#define ROTRIGHT(a,b) (((a) >> (b)) | ((a) << (32-(b))))
#define CH(x,y,z) (((x) & (y)) ^ (~(x) & (z)))
#define MAJ(x,y,z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))
#define EP0(x) (ROTRIGHT(x,2) ^ ROTRIGHT(x,13) ^ ROTRIGHT(x,22))
#define EP1(x) (ROTRIGHT(x,6) ^ ROTRIGHT(x,11) ^ ROTRIGHT(x,25))
#define SIG0(x) (ROTRIGHT(x,7) ^ ROTRIGHT(x,18) ^ ((x) >> 3))
#define SIG1(x) (ROTRIGHT(x,17) ^ ROTRIGHT(x,19) ^ ((x) >> 10))

#define SWAP32(x) (rotate((unsigned int)(x), 24U) & 0x00FF00FF | rotate((unsigned int)(x), 8U) & 0xFF00FF00)

__device__ void sha256_transform( unsigned int *state, const unsigned char *data) {
    unsigned int a, b, c, d, e, f, g, h, t1, t2;
    unsigned int m[64];
    
    // Load data into message schedule (Big Endian)
    for (int i = 0, j = 0; i < 16; ++i, j += 4) {
        m[i] = ((unsigned int)data[j] << 24) | ((unsigned int)data[j + 1] << 16) | ((unsigned int)data[j + 2] << 8) | ((unsigned int)data[j + 3]);
    }
    
    for (int i = 16; i < 64; ++i) {
        m[i] = SIG1(m[i - 2]) + m[i - 7] + SIG0(m[i - 15]) + m[i - 16];
    }
    
    a = state[0]; b = state[1]; c = state[2]; d = state[3];
    e = state[4]; f = state[5]; g = state[6]; h = state[7];
    
    for (int i = 0; i < 64; ++i) {
        t1 = h + EP1(e) + CH(e, f, g) + K256[i] + m[i];
        t2 = EP0(a) + MAJ(a, b, c);
        h = g; g = f; f = e; e = d + t1;
        d = c; c = b; b = a; a = t1 + t2;
    }
    
    state[0] += a; state[1] += b; state[2] += c; state[3] += d;
    state[4] += e; state[5] += f; state[6] += g; state[7] += h;
}

__device__ void sha256_init(unsigned int *state) {
    state[0] = 0x6a09e667; state[1] = 0xbb67ae85; state[2] = 0x3c6ef372; state[3] = 0xa54ff53a;
    state[4] = 0x510e527f; state[5] = 0x9b05688c; state[6] = 0x1f83d9ab; state[7] = 0x5be0cd19;
}

__device__ void sha256(const unsigned char *msg, unsigned int len, unsigned char *digest) {
    unsigned int state[8];
    sha256_init(state);
    
    unsigned int processed = 0;
    while (processed + 64 <= len) {
        sha256_transform(state, msg + processed);
        processed += 64;
    }
    
    unsigned char block[64];
    unsigned int rem = len - processed;
    for(int i=0; i<rem; i++) block[i] = msg[processed + i];
    
    block[rem] = 0x80;
    for(int i=rem+1; i<64; i++) block[i] = 0;
    
    if (rem >= 56) {
        sha256_transform(state, block);
        for(int i=0; i<64; i++) block[i] = 0;
    }
    
    // Append length in bits (Big Endian 64-bit)
    unsigned long long bitlen = (unsigned long long)len * 8;
    for(int i=0; i<8; i++) {
        block[63-i] = (bitlen >> (i*8)) & 0xFF;
    }
    sha256_transform(state, block);
    
    // Output Big Endian
    for(int i=0; i<8; i++) {
        unsigned int s = state[i];
        digest[i*4+0] = (s >> 24) & 0xFF;
        digest[i*4+1] = (s >> 16) & 0xFF;
        digest[i*4+2] = (s >> 8) & 0xFF;
        digest[i*4+3] = s & 0xFF;
    }
}

    
    // === RIPEMD160 ===
    
// RIPEMD-160 Implementation - Exactly matching bitcoin/bitcoin
// https://github.com/bitcoin/bitcoin/blob/master/src/crypto/ripemd160.cpp

#define ROL(x, n) (((x) << (n)) | ((x) >> (32-(n))))

__device__ unsigned int inline f1(unsigned int x, unsigned int y, unsigned int z) { return x ^ y ^ z; }
__device__ unsigned int inline f2(unsigned int x, unsigned int y, unsigned int z) { return (x & y) | (~x & z); }
__device__ unsigned int inline f3(unsigned int x, unsigned int y, unsigned int z) { return (x | ~y) ^ z; }
__device__ unsigned int inline f4(unsigned int x, unsigned int y, unsigned int z) { return (x & z) | (y & ~z); }
__device__ unsigned int inline f5(unsigned int x, unsigned int y, unsigned int z) { return x ^ (y | ~z); }

#define R11(a, b, c, d, e, w, s) { a = ROL(a + f1(b,c,d) + w + 0x00000000U, s) + e; c = ROL(c, 10); }
#define R21(a, b, c, d, e, w, s) { a = ROL(a + f2(b,c,d) + w + 0x5a827999U, s) + e; c = ROL(c, 10); }
#define R31(a, b, c, d, e, w, s) { a = ROL(a + f3(b,c,d) + w + 0x6ed9eba1U, s) + e; c = ROL(c, 10); }
#define R41(a, b, c, d, e, w, s) { a = ROL(a + f4(b,c,d) + w + 0x8f1bbcdcU, s) + e; c = ROL(c, 10); }
#define R51(a, b, c, d, e, w, s) { a = ROL(a + f5(b,c,d) + w + 0xa953fd4eU, s) + e; c = ROL(c, 10); }

#define R12(a, b, c, d, e, w, s) { a = ROL(a + f5(b,c,d) + w + 0x50a28be6U, s) + e; c = ROL(c, 10); }
#define R22(a, b, c, d, e, w, s) { a = ROL(a + f4(b,c,d) + w + 0x5c4dd124U, s) + e; c = ROL(c, 10); }
#define R32(a, b, c, d, e, w, s) { a = ROL(a + f3(b,c,d) + w + 0x6d703ef3U, s) + e; c = ROL(c, 10); }
#define R42(a, b, c, d, e, w, s) { a = ROL(a + f2(b,c,d) + w + 0x7a6d76e9U, s) + e; c = ROL(c, 10); }
#define R52(a, b, c, d, e, w, s) { a = ROL(a + f1(b,c,d) + w + 0x00000000U, s) + e; c = ROL(c, 10); }

__device__ void ripemd160_transform(unsigned int *s, const unsigned char *chunk) {
    unsigned int a1 = s[0], b1 = s[1], c1 = s[2], d1 = s[3], e1 = s[4];
    unsigned int a2 = a1, b2 = b1, c2 = c1, d2 = d1, e2 = e1;
    
    // Read as little-endian
    unsigned int w0  = ((unsigned int)chunk[0])  | ((unsigned int)chunk[1]<<8)  | ((unsigned int)chunk[2]<<16)  | ((unsigned int)chunk[3]<<24);
    unsigned int w1  = ((unsigned int)chunk[4])  | ((unsigned int)chunk[5]<<8)  | ((unsigned int)chunk[6]<<16)  | ((unsigned int)chunk[7]<<24);
    unsigned int w2  = ((unsigned int)chunk[8])  | ((unsigned int)chunk[9]<<8)  | ((unsigned int)chunk[10]<<16) | ((unsigned int)chunk[11]<<24);
    unsigned int w3  = ((unsigned int)chunk[12]) | ((unsigned int)chunk[13]<<8) | ((unsigned int)chunk[14]<<16) | ((unsigned int)chunk[15]<<24);
    unsigned int w4  = ((unsigned int)chunk[16]) | ((unsigned int)chunk[17]<<8) | ((unsigned int)chunk[18]<<16) | ((unsigned int)chunk[19]<<24);
    unsigned int w5  = ((unsigned int)chunk[20]) | ((unsigned int)chunk[21]<<8) | ((unsigned int)chunk[22]<<16) | ((unsigned int)chunk[23]<<24);
    unsigned int w6  = ((unsigned int)chunk[24]) | ((unsigned int)chunk[25]<<8) | ((unsigned int)chunk[26]<<16) | ((unsigned int)chunk[27]<<24);
    unsigned int w7  = ((unsigned int)chunk[28]) | ((unsigned int)chunk[29]<<8) | ((unsigned int)chunk[30]<<16) | ((unsigned int)chunk[31]<<24);
    unsigned int w8  = ((unsigned int)chunk[32]) | ((unsigned int)chunk[33]<<8) | ((unsigned int)chunk[34]<<16) | ((unsigned int)chunk[35]<<24);
    unsigned int w9  = ((unsigned int)chunk[36]) | ((unsigned int)chunk[37]<<8) | ((unsigned int)chunk[38]<<16) | ((unsigned int)chunk[39]<<24);
    unsigned int w10 = ((unsigned int)chunk[40]) | ((unsigned int)chunk[41]<<8) | ((unsigned int)chunk[42]<<16) | ((unsigned int)chunk[43]<<24);
    unsigned int w11 = ((unsigned int)chunk[44]) | ((unsigned int)chunk[45]<<8) | ((unsigned int)chunk[46]<<16) | ((unsigned int)chunk[47]<<24);
    unsigned int w12 = ((unsigned int)chunk[48]) | ((unsigned int)chunk[49]<<8) | ((unsigned int)chunk[50]<<16) | ((unsigned int)chunk[51]<<24);
    unsigned int w13 = ((unsigned int)chunk[52]) | ((unsigned int)chunk[53]<<8) | ((unsigned int)chunk[54]<<16) | ((unsigned int)chunk[55]<<24);
    unsigned int w14 = ((unsigned int)chunk[56]) | ((unsigned int)chunk[57]<<8) | ((unsigned int)chunk[58]<<16) | ((unsigned int)chunk[59]<<24);
    unsigned int w15 = ((unsigned int)chunk[60]) | ((unsigned int)chunk[61]<<8) | ((unsigned int)chunk[62]<<16) | ((unsigned int)chunk[63]<<24);

    // Round 1 - Exactly as in bitcoin
    R11(a1, b1, c1, d1, e1, w0, 11);  R12(a2, b2, c2, d2, e2, w5, 8);
    R11(e1, a1, b1, c1, d1, w1, 14);  R12(e2, a2, b2, c2, d2, w14, 9);
    R11(d1, e1, a1, b1, c1, w2, 15);  R12(d2, e2, a2, b2, c2, w7, 9);
    R11(c1, d1, e1, a1, b1, w3, 12);  R12(c2, d2, e2, a2, b2, w0, 11);
    R11(b1, c1, d1, e1, a1, w4, 5);   R12(b2, c2, d2, e2, a2, w9, 13);
    R11(a1, b1, c1, d1, e1, w5, 8);   R12(a2, b2, c2, d2, e2, w2, 15);
    R11(e1, a1, b1, c1, d1, w6, 7);   R12(e2, a2, b2, c2, d2, w11, 15);
    R11(d1, e1, a1, b1, c1, w7, 9);   R12(d2, e2, a2, b2, c2, w4, 5);
    R11(c1, d1, e1, a1, b1, w8, 11);  R12(c2, d2, e2, a2, b2, w13, 7);
    R11(b1, c1, d1, e1, a1, w9, 13);  R12(b2, c2, d2, e2, a2, w6, 7);
    R11(a1, b1, c1, d1, e1, w10, 14); R12(a2, b2, c2, d2, e2, w15, 8);
    R11(e1, a1, b1, c1, d1, w11, 15); R12(e2, a2, b2, c2, d2, w8, 11);
    R11(d1, e1, a1, b1, c1, w12, 6);  R12(d2, e2, a2, b2, c2, w1, 14);
    R11(c1, d1, e1, a1, b1, w13, 7);  R12(c2, d2, e2, a2, b2, w10, 14);
    R11(b1, c1, d1, e1, a1, w14, 9);  R12(b2, c2, d2, e2, a2, w3, 12);
    R11(a1, b1, c1, d1, e1, w15, 8);  R12(a2, b2, c2, d2, e2, w12, 6);

    // Round 2
    R21(e1, a1, b1, c1, d1, w7, 7);   R22(e2, a2, b2, c2, d2, w6, 9);
    R21(d1, e1, a1, b1, c1, w4, 6);   R22(d2, e2, a2, b2, c2, w11, 13);
    R21(c1, d1, e1, a1, b1, w13, 8);  R22(c2, d2, e2, a2, b2, w3, 15);
    R21(b1, c1, d1, e1, a1, w1, 13);  R22(b2, c2, d2, e2, a2, w7, 7);
    R21(a1, b1, c1, d1, e1, w10, 11); R22(a2, b2, c2, d2, e2, w0, 12);
    R21(e1, a1, b1, c1, d1, w6, 9);   R22(e2, a2, b2, c2, d2, w13, 8);
    R21(d1, e1, a1, b1, c1, w15, 7);  R22(d2, e2, a2, b2, c2, w5, 9);
    R21(c1, d1, e1, a1, b1, w3, 15);  R22(c2, d2, e2, a2, b2, w10, 11);
    R21(b1, c1, d1, e1, a1, w12, 7);  R22(b2, c2, d2, e2, a2, w14, 7);
    R21(a1, b1, c1, d1, e1, w0, 12);  R22(a2, b2, c2, d2, e2, w15, 7);
    R21(e1, a1, b1, c1, d1, w9, 15);  R22(e2, a2, b2, c2, d2, w8, 12);
    R21(d1, e1, a1, b1, c1, w5, 9);   R22(d2, e2, a2, b2, c2, w12, 7);
    R21(c1, d1, e1, a1, b1, w2, 11);  R22(c2, d2, e2, a2, b2, w4, 6);
    R21(b1, c1, d1, e1, a1, w14, 7);  R22(b2, c2, d2, e2, a2, w9, 15);
    R21(a1, b1, c1, d1, e1, w11, 13); R22(a2, b2, c2, d2, e2, w1, 13);
    R21(e1, a1, b1, c1, d1, w8, 12);  R22(e2, a2, b2, c2, d2, w2, 11);

    // Round 3
    R31(d1, e1, a1, b1, c1, w3, 11);  R32(d2, e2, a2, b2, c2, w15, 9);
    R31(c1, d1, e1, a1, b1, w10, 13); R32(c2, d2, e2, a2, b2, w5, 7);
    R31(b1, c1, d1, e1, a1, w14, 6);  R32(b2, c2, d2, e2, a2, w1, 15);
    R31(a1, b1, c1, d1, e1, w4, 7);   R32(a2, b2, c2, d2, e2, w3, 11);
    R31(e1, a1, b1, c1, d1, w9, 14);  R32(e2, a2, b2, c2, d2, w7, 8);
    R31(d1, e1, a1, b1, c1, w15, 9);  R32(d2, e2, a2, b2, c2, w14, 6);
    R31(c1, d1, e1, a1, b1, w8, 13);  R32(c2, d2, e2, a2, b2, w6, 6);
    R31(b1, c1, d1, e1, a1, w1, 15);  R32(b2, c2, d2, e2, a2, w9, 14);
    R31(a1, b1, c1, d1, e1, w2, 14);  R32(a2, b2, c2, d2, e2, w11, 12);
    R31(e1, a1, b1, c1, d1, w7, 8);   R32(e2, a2, b2, c2, d2, w8, 13);
    R31(d1, e1, a1, b1, c1, w0, 13);  R32(d2, e2, a2, b2, c2, w12, 5);
    R31(c1, d1, e1, a1, b1, w6, 6);   R32(c2, d2, e2, a2, b2, w2, 14);
    R31(b1, c1, d1, e1, a1, w13, 5);  R32(b2, c2, d2, e2, a2, w10, 13);
    R31(a1, b1, c1, d1, e1, w11, 12); R32(a2, b2, c2, d2, e2, w0, 13);
    R31(e1, a1, b1, c1, d1, w5, 7);   R32(e2, a2, b2, c2, d2, w4, 7);
    R31(d1, e1, a1, b1, c1, w12, 5);  R32(d2, e2, a2, b2, c2, w13, 5);

    // Round 4
    R41(c1, d1, e1, a1, b1, w1, 11);  R42(c2, d2, e2, a2, b2, w8, 15);
    R41(b1, c1, d1, e1, a1, w9, 12);  R42(b2, c2, d2, e2, a2, w6, 5);
    R41(a1, b1, c1, d1, e1, w11, 14); R42(a2, b2, c2, d2, e2, w4, 8);
    R41(e1, a1, b1, c1, d1, w10, 15); R42(e2, a2, b2, c2, d2, w1, 11);
    R41(d1, e1, a1, b1, c1, w0, 14);  R42(d2, e2, a2, b2, c2, w3, 14);
    R41(c1, d1, e1, a1, b1, w8, 15);  R42(c2, d2, e2, a2, b2, w11, 14);
    R41(b1, c1, d1, e1, a1, w12, 9);  R42(b2, c2, d2, e2, a2, w15, 6);
    R41(a1, b1, c1, d1, e1, w4, 8);   R42(a2, b2, c2, d2, e2, w0, 14);
    R41(e1, a1, b1, c1, d1, w13, 9);  R42(e2, a2, b2, c2, d2, w5, 6);
    R41(d1, e1, a1, b1, c1, w3, 14);  R42(d2, e2, a2, b2, c2, w12, 9);
    R41(c1, d1, e1, a1, b1, w7, 5);   R42(c2, d2, e2, a2, b2, w2, 12);
    R41(b1, c1, d1, e1, a1, w15, 6);  R42(b2, c2, d2, e2, a2, w13, 9);
    R41(a1, b1, c1, d1, e1, w14, 8);  R42(a2, b2, c2, d2, e2, w9, 12);
    R41(e1, a1, b1, c1, d1, w5, 6);   R42(e2, a2, b2, c2, d2, w7, 5);
    R41(d1, e1, a1, b1, c1, w6, 5);   R42(d2, e2, a2, b2, c2, w10, 15);
    R41(c1, d1, e1, a1, b1, w2, 12);  R42(c2, d2, e2, a2, b2, w14, 8);

    // Round 5
    R51(b1, c1, d1, e1, a1, w4, 9);   R52(b2, c2, d2, e2, a2, w12, 8);
    R51(a1, b1, c1, d1, e1, w0, 15);  R52(a2, b2, c2, d2, e2, w15, 5);
    R51(e1, a1, b1, c1, d1, w5, 5);   R52(e2, a2, b2, c2, d2, w10, 12);
    R51(d1, e1, a1, b1, c1, w9, 11);  R52(d2, e2, a2, b2, c2, w4, 9);
    R51(c1, d1, e1, a1, b1, w7, 6);   R52(c2, d2, e2, a2, b2, w1, 12);
    R51(b1, c1, d1, e1, a1, w12, 8);  R52(b2, c2, d2, e2, a2, w5, 5);
    R51(a1, b1, c1, d1, e1, w2, 13);  R52(a2, b2, c2, d2, e2, w8, 14);
    R51(e1, a1, b1, c1, d1, w10, 12); R52(e2, a2, b2, c2, d2, w7, 6);
    R51(d1, e1, a1, b1, c1, w14, 5);  R52(d2, e2, a2, b2, c2, w6, 8);
    R51(c1, d1, e1, a1, b1, w1, 12);  R52(c2, d2, e2, a2, b2, w2, 13);
    R51(b1, c1, d1, e1, a1, w3, 13);  R52(b2, c2, d2, e2, a2, w13, 6);
    R51(a1, b1, c1, d1, e1, w8, 14);  R52(a2, b2, c2, d2, e2, w14, 5);
    R51(e1, a1, b1, c1, d1, w11, 11); R52(e2, a2, b2, c2, d2, w0, 15);
    R51(d1, e1, a1, b1, c1, w6, 8);   R52(d2, e2, a2, b2, c2, w3, 13);
    R51(c1, d1, e1, a1, b1, w15, 5);  R52(c2, d2, e2, a2, b2, w9, 11);
    R51(b1, c1, d1, e1, a1, w13, 6);  R52(b2, c2, d2, e2, a2, w11, 11);

    // Finalize
    unsigned int t = s[1] + c1 + d2;
    s[1] = s[2] + d1 + e2;
    s[2] = s[3] + e1 + a2;
    s[3] = s[4] + a1 + b2;
    s[4] = s[0] + b1 + c2;
    s[0] = t;
}

__device__ void ripemd160_init(unsigned int *state) {
    state[0] = 0x67452301;
    state[1] = 0xefcdab89;
    state[2] = 0x98badcfe;
    state[3] = 0x10325476;
    state[4] = 0xc3d2e1f0;
}

// Hash 32 bytes (SHA256 output for Hash160)
__device__ void ripemd160_32(const unsigned char *msg, unsigned char *digest) {
    unsigned int state[5];
    ripemd160_init(state);
    
    unsigned char block[64];
    for(int i=0; i<32; i++) block[i] = msg[i];
    
    // Padding
    block[32] = 0x80;
    for(int i=33; i<56; i++) block[i] = 0;
    
    // Length in bits (32*8 = 256), Little Endian 64-bit
    block[56] = 0x00;
    block[57] = 0x01;
    block[58] = 0x00;
    block[59] = 0x00;
    block[60] = 0x00;
    block[61] = 0x00;
    block[62] = 0x00;
    block[63] = 0x00;
    
    ripemd160_transform(state, block);
    
    // Output Little Endian
    for(int i=0; i<5; i++) {
        unsigned int v = state[i];
        digest[i*4+0] = v & 0xFF;
        digest[i*4+1] = (v >> 8) & 0xFF;
        digest[i*4+2] = (v >> 16) & 0xFF;
        digest[i*4+3] = (v >> 24) & 0xFF;
    }
}

    
    // === SECP256K1 FIELD/POINT ===
    #define WINDOW_A 5
#define WINDOW_G 14

/** The number of entries a table with precomputed multiples needs to have. */
#define ECMULT_TABLE_SIZE(w) (1 << ((w)-2))

#define ECMULT_TABLE_GET(r,pre,n,w,neg) do { \
    if ((n) > 0) \
        *(r) = (pre)[((n)-1)/2]; \
    else \
        (neg)((r), &(pre)[(-(n)-1)/2]); \
} while(0)



#define ECMULT_TABLE_GET_GEJ(r,pre,n,w) do { \
    if ((n) > 0) \
        *(r) = (pre)[((n)-1)/2]; \
    else \
        secp256k1_gej_neg((r), &(pre)[(-(n)-1)/2]); \
} while(0)


#define ECMULT_TABLE_GET_GE(r,pre,n,w) do { \
    if ((n) > 0) \
        *(r) = (pre)[((n)-1)/2]; \
    else \
        secp256k1_ge_neg((r), &(pre)[(-(n)-1)/2]); \
} while(0)


typedef struct {
    // X = sum(i=0..9, elem[i]*2^26) mod n
    unsigned int n[10];
} secp256k1_fe_t;

typedef struct {
    secp256k1_fe_t x;
    secp256k1_fe_t y;
    int infinity; // whether this represents the point at infinity
} secp256k1_ge_t;

    typedef struct {
    secp256k1_fe_t x; // actual X: x/z^2
    secp256k1_fe_t y; // actual Y: y/z^3
    secp256k1_fe_t z;
    int infinity; // whether this represents the point at infinity
} secp256k1_gej_t;

typedef struct {
	secp256k1_gej_t a;
	char wnaf_na[257];
	short bits_na;
	short wnaf_ng_1[129];
	short bits_ng_1;
	short wnaf_ng_128[129];
	short bits_ng_128;
} ecmult_params_device_t;

typedef struct {
    // For accelerating the computation of a*P + b*G:
    secp256k1_ge_t pre_g[ECMULT_TABLE_SIZE(WINDOW_G)];    // odd multiples of the generator
    secp256k1_ge_t pre_g_128[ECMULT_TABLE_SIZE(WINDOW_G)]; // odd multiples of 2^128*generator

    // For accelerating the computation of a*G:
    // To harden against timing attacks, use the following mechanism:
    // * Break up the multiplicand into groups of 4 bits, called n_0, n_1, n_2, ..., n_63.
    // * Compute sum((n_i + 1) * 16^i * G, i=0..63).
    // * Subtract sum(1 * 16^i * G, i=0..63).
    // For each i, and each of the 16 possible values of n_i, ((n_i + 1) * 16^i * G) is
    // precomputed (call it prec(i,n_i), as well as -sum(1 * 16^i * G) (called fin).
    // The formula now becomes sum(prec(i, n_i), i=0..63) + fin.
    // To make memory access uniform, the bytes of prec(i,n_i) are sliced per value of n_i.
    unsigned char prec[64][sizeof(secp256k1_ge_t)][16]; // prec[j][k][i] = k'th byte of (16^j * (i+1) * G)
    secp256k1_ge_t fin; // -(sum(prec[j][0], j=0..63))
} secp256k1_ecmult_consts_t;

typedef struct {
    unsigned char v[32];
} b32_t;
    
__device__ void secp256k1_gej_set_infinity(secp256k1_gej_t *r) {
    r->infinity = 1;
}
__device__ void secp256k1_gej_neg(secp256k1_gej_t *r,  const secp256k1_gej_t *a);
__device__ void secp256k1_ge_neg(secp256k1_ge_t *r, const secp256k1_ge_t *a);


void secp256k1_ecmult_table_precomp_gej( secp256k1_gej_t *pre,  secp256k1_gej_t *a, int w);
__device__ void secp256k1_gej_double(secp256k1_gej_t *r, const secp256k1_gej_t *a);
__device__ void secp256k1_gej_add( secp256k1_gej_t *r, const secp256k1_gej_t *a,  const secp256k1_gej_t *b);
__device__ void secp256k1_gej_add_local(secp256k1_gej_t *pr, const secp256k1_gej_t *pa, const secp256k1_gej_t *pb);
__device__ void secp256k1_gej_add_ge(secp256k1_gej_t *r, const secp256k1_gej_t *a, const secp256k1_ge_t *b);

__device__ void secp256k1_fe_normalize(secp256k1_fe_t *r);    
__device__ void secp256k1_fe_mul(secp256k1_fe_t *r, const secp256k1_fe_t *a, const secp256k1_fe_t *b);
__device__ void secp256k1_fe_mul_int(secp256k1_fe_t *r, int a);
__device__ void secp256k1_fe_add(secp256k1_fe_t *r, const secp256k1_fe_t *a);
__device__ void secp256k1_fe_sqr(secp256k1_fe_t *r, const secp256k1_fe_t *a);
__device__ void secp256k1_fe_negate(secp256k1_fe_t *r, const secp256k1_fe_t *a, int m);
__device__ int secp256k1_fe_is_zero(const secp256k1_fe_t *a);
__device__ void secp256k1_fe_get_b32(unsigned char *r, const secp256k1_fe_t *a);
__device__ void secp256k1_gej_get_x(secp256k1_fe_t *r, const secp256k1_gej_t *a);
__device__ void secp256k1_fe_inv_var(secp256k1_fe_t *r, const secp256k1_fe_t *a);

__device__ void secp256k1_ecmult_table_precomp_gej( secp256k1_gej_t *pre,  secp256k1_gej_t *pa, int w) {
    int ind = (blockIdx.x * blockDim.x + threadIdx.x);
    int sz = (1 << (w-2));
    secp256k1_gej_t a = pa[ind];
    pre[ind * sz] = a;
    secp256k1_gej_t d; secp256k1_gej_double(&d, &a);
    for(int i = 1; i < sz; i++) {
        secp256k1_gej_add(&pre[ind * sz + i], &d, &pre[ind * sz + i - 1]);
    }
}

__global__ void test_ecmult_table_precomp_gej( secp256k1_gej_t *pre,  secp256k1_gej_t *pa, int w) {
    int ind = (blockIdx.x * blockDim.x + threadIdx.x);
    pre[ind] = pa[ind];
    // pre[ind].infinity = 2;
}

__global__ void secp256k1_ecmult( b32_t *pr,  secp256k1_gej_t *ppre_a,  ecmult_params_device_t *pParams, const secp256k1_ecmult_consts_t *mc) {
    int ind = (blockIdx.x * blockDim.x + threadIdx.x);
    int sz = (1 << (WINDOW_A-2));

    ecmult_params_device_t params = pParams[ind];
     secp256k1_gej_t *pre_a = &ppre_a[ind * sz];
     b32_t *ppr = &pr[ind];
    
    secp256k1_gej_t r;
    secp256k1_gej_set_infinity(&r);
    secp256k1_gej_t tmpj;
    secp256k1_ge_t tmpa;

    short bits = max(params.bits_na, params.bits_ng_1);
    bits = max(bits, params.bits_ng_128);
    for (int i=bits-1; i>=0; i--) {
        secp256k1_gej_double(&r, &r);
        int n;
        if (i < params.bits_na && (n = params.wnaf_na[i])) {
            ECMULT_TABLE_GET_GEJ(&tmpj, pre_a, n, WINDOW_A);
            secp256k1_gej_add_local(&r, &r, &tmpj);
        }

        if (i < params.bits_ng_1 && (n = params.wnaf_ng_1[i])) {
            ECMULT_TABLE_GET_GE(&tmpa, mc->pre_g, n, WINDOW_G);
            secp256k1_gej_add_ge(&r, &r, &tmpa);
        }
        if (i < params.bits_ng_128 && (n = params.wnaf_ng_128[i])) {
            ECMULT_TABLE_GET_GE(&tmpa, mc->pre_g_128, n, WINDOW_G);
            secp256k1_gej_add_ge(&r, &r, &tmpa);
        }
    }

	secp256k1_fe_t xr; secp256k1_gej_get_x(&xr, &r);
	secp256k1_fe_normalize(&xr);
    b32_t b32;
	secp256k1_fe_get_b32(b32.v, &xr);
    *ppr = b32;
}
                      
__device__ void secp256k1_gej_neg(secp256k1_gej_t *r,  const secp256k1_gej_t *a) {
    r->infinity = a->infinity;
    r->x = a->x;
    r->y = a->y;
    r->z = a->z;
    secp256k1_fe_normalize(&r->y);
    secp256k1_fe_negate(&r->y, &r->y, 1);
}

__device__ void secp256k1_ge_neg(secp256k1_ge_t *r, const secp256k1_ge_t *a) {
    r->infinity = a->infinity;
    r->x = a->x;
    r->y = a->y;
    secp256k1_fe_normalize(&r->y);
    secp256k1_fe_negate(&r->y, &r->y, 1);
}

typedef unsigned int uint32_t;
typedef unsigned long uint64_t;

__device__ void secp256k1_fe_normalize(secp256k1_fe_t *r) {
//    fog("normalize in: ", r);
    uint32_t c;
    c = r->n[0];
    uint32_t t0 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[1];
    uint32_t t1 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[2];
    uint32_t t2 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[3];
    uint32_t t3 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[4];
    uint32_t t4 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[5];
    uint32_t t5 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[6];
    uint32_t t6 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[7];
    uint32_t t7 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[8];
    uint32_t t8 = c & 0x3FFFFFFUL;
    c = (c >> 26) + r->n[9];
    uint32_t t9 = c & 0x03FFFFFUL;
    c >>= 22;
/*    r->n[0] = t0; r->n[1] = t1; r->n[2] = t2; r->n[3] = t3; r->n[4] = t4;
    r->n[5] = t5; r->n[6] = t6; r->n[7] = t7; r->n[8] = t8; r->n[9] = t9;
    fog("         tm1: ", r);
    fprintf(stderr, "out c= %08lx\n", (unsigned long)c);*/

    // The following code will not modify the t's if c is initially 0.
    uint32_t d = c * 0x3D1UL + t0;
    t0 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t1 + c*0x40;
    t1 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t2;
    t2 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t3;
    t3 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t4;
    t4 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t5;
    t5 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t6;
    t6 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t7;
    t7 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t8;
    t8 = d & 0x3FFFFFFUL;
    d = (d >> 26) + t9;
    t9 = d & 0x03FFFFFUL;
/*    r->n[0] = t0; r->n[1] = t1; r->n[2] = t2; r->n[3] = t3; r->n[4] = t4;
    r->n[5] = t5; r->n[6] = t6; r->n[7] = t7; r->n[8] = t8; r->n[9] = t9;
    fog("         tm2: ", r); */

    // Subtract p if result >= p
    uint64_t low = ((uint64_t)t1 << 26) | t0;
    uint64_t mask = -(long)((t9 < 0x03FFFFFUL) | (t8 < 0x3FFFFFFUL) | (t7 < 0x3FFFFFFUL) | (t6 < 0x3FFFFFFUL) | (t5 < 0x3FFFFFFUL) | (t4 < 0x3FFFFFFUL) | (t3 < 0x3FFFFFFUL) | (t2 < 0x3FFFFFFUL) | (low < 0xFFFFEFFFFFC2FUL));
    t9 &= mask;
    t8 &= mask;
    t7 &= mask;
    t6 &= mask;
    t5 &= mask;
    t4 &= mask;
    t3 &= mask;
    t2 &= mask;
    low -= (~mask & 0xFFFFEFFFFFC2FUL);

    // push internal variables back
    r->n[0] = low & 0x3FFFFFFUL; r->n[1] = (low >> 26) & 0x3FFFFFFUL; r->n[2] = t2; r->n[3] = t3; r->n[4] = t4;
    r->n[5] = t5; r->n[6] = t6; r->n[7] = t7; r->n[8] = t8; r->n[9] = t9;
/*    fog("         out: ", r);*/

#ifdef VERIFY
    r->magnitude = 1;
    r->normalized = 1;
#endif
}

__device__ void static inline secp256k1_fe_set_int(secp256k1_fe_t *r, int a) {
    r->n[0] = a;
    r->n[1] = r->n[2] = r->n[3] = r->n[4] = r->n[5] = r->n[6] = r->n[7] = r->n[8] = r->n[9] = 0;
#ifdef VERIFY
    r->magnitude = 1;
    r->normalized = 1;
#endif
}

// TODO: not constant time!
__device__ int secp256k1_fe_is_zero(const secp256k1_fe_t *a) {
#ifdef VERIFY
    assert(a->normalized);
#endif
    return (a->n[0] == 0 && a->n[1] == 0 && a->n[2] == 0 && a->n[3] == 0 && a->n[4] == 0 && a->n[5] == 0 && a->n[6] == 0 && a->n[7] == 0 && a->n[8] == 0 && a->n[9] == 0);
}

__device__ int static inline secp256k1_fe_is_odd(const secp256k1_fe_t *a) {
#ifdef VERIFY
    assert(a->normalized);
#endif
    return a->n[0] & 1;
}

// TODO: not constant time!
__device__ int secp256k1_fe_equal(const secp256k1_fe_t *a, const secp256k1_fe_t *b) {
#ifdef VERIFY
    assert(a->normalized);
    assert(b->normalized);
#endif
    return (a->n[0] == b->n[0] && a->n[1] == b->n[1] && a->n[2] == b->n[2] && a->n[3] == b->n[3] && a->n[4] == b->n[4] &&
            a->n[5] == b->n[5] && a->n[6] == b->n[6] && a->n[7] == b->n[7] && a->n[8] == b->n[8] && a->n[9] == b->n[9]);
}

__device__ void secp256k1_fe_set_b32(secp256k1_fe_t *r, const unsigned char *a) {
    r->n[0] = r->n[1] = r->n[2] = r->n[3] = r->n[4] = 0;
    r->n[5] = r->n[6] = r->n[7] = r->n[8] = r->n[9] = 0;
    for (int i=0; i<32; i++) {
        for (int j=0; j<4; j++) {
            int limb = (8*i+2*j)/26;
            int shift = (8*i+2*j)%26;
            r->n[limb] |= (uint32_t)((a[31-i] >> (2*j)) & 0x3) << shift;
        }
    }
#ifdef VERIFY
    r->magnitude = 1;
    r->normalized = 1;
#endif
}

/** Convert a field element to a 32-byte big endian value. Requires the input to be normalized */
__device__ void secp256k1_fe_get_b32(unsigned char *r, const secp256k1_fe_t *a) {
#ifdef VERIFY
    assert(a->normalized);
#endif
    for (int i=0; i<32; i++) {
        int c = 0;
        for (int j=0; j<4; j++) {
            int limb = (8*i+2*j)/26;
            int shift = (8*i+2*j)%26;
            c |= ((a->n[limb] >> shift) & 0x3) << (2 * j);
        }
        r[31-i] = c;
    }
}

__device__ void secp256k1_fe_negate(secp256k1_fe_t *r, const secp256k1_fe_t *a, int m) {
#ifdef VERIFY
    assert(a->magnitude <= m);
    r->magnitude = m + 1;
    r->normalized = 0;
#endif
    r->n[0] = 0x3FFFC2FUL * (m + 1) - a->n[0];
    r->n[1] = 0x3FFFFBFUL * (m + 1) - a->n[1];
    r->n[2] = 0x3FFFFFFUL * (m + 1) - a->n[2];
    r->n[3] = 0x3FFFFFFUL * (m + 1) - a->n[3];
    r->n[4] = 0x3FFFFFFUL * (m + 1) - a->n[4];
    r->n[5] = 0x3FFFFFFUL * (m + 1) - a->n[5];
    r->n[6] = 0x3FFFFFFUL * (m + 1) - a->n[6];
    r->n[7] = 0x3FFFFFFUL * (m + 1) - a->n[7];
    r->n[8] = 0x3FFFFFFUL * (m + 1) - a->n[8];
    r->n[9] = 0x03FFFFFUL * (m + 1) - a->n[9];
}

__device__ void secp256k1_fe_mul_int(secp256k1_fe_t *r, int a) {
#ifdef VERIFY
    r->magnitude *= a;
    r->normalized = 0;
#endif
    r->n[0] *= a;
    r->n[1] *= a;
    r->n[2] *= a;
    r->n[3] *= a;
    r->n[4] *= a;
    r->n[5] *= a;
    r->n[6] *= a;
    r->n[7] *= a;
    r->n[8] *= a;
    r->n[9] *= a;
}

__device__ void secp256k1_fe_add(secp256k1_fe_t *r, const secp256k1_fe_t *a) {
#ifdef VERIFY
    r->magnitude += a->magnitude;
    r->normalized = 0;
#endif
    r->n[0] += a->n[0];
    r->n[1] += a->n[1];
    r->n[2] += a->n[2];
    r->n[3] += a->n[3];
    r->n[4] += a->n[4];
    r->n[5] += a->n[5];
    r->n[6] += a->n[6];
    r->n[7] += a->n[7];
    r->n[8] += a->n[8];
    r->n[9] += a->n[9];
}

__device__ void secp256k1_fe_mul_inner(const uint32_t *a, const uint32_t *b, uint32_t *r) {
    uint64_t c = (uint64_t)a[0] * b[0];
    uint32_t t0 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[1] +
            (uint64_t)a[1] * b[0];
    uint32_t t1 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[2] +
            (uint64_t)a[1] * b[1] +
            (uint64_t)a[2] * b[0];
    uint32_t t2 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[3] +
            (uint64_t)a[1] * b[2] +
            (uint64_t)a[2] * b[1] +
            (uint64_t)a[3] * b[0];
    uint32_t t3 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[4] +
            (uint64_t)a[1] * b[3] +
            (uint64_t)a[2] * b[2] +
            (uint64_t)a[3] * b[1] +
            (uint64_t)a[4] * b[0];
    uint32_t t4 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[5] +
            (uint64_t)a[1] * b[4] +
            (uint64_t)a[2] * b[3] +
            (uint64_t)a[3] * b[2] +
            (uint64_t)a[4] * b[1] +
            (uint64_t)a[5] * b[0];
    uint32_t t5 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[6] +
            (uint64_t)a[1] * b[5] +
            (uint64_t)a[2] * b[4] +
            (uint64_t)a[3] * b[3] +
            (uint64_t)a[4] * b[2] +
            (uint64_t)a[5] * b[1] +
            (uint64_t)a[6] * b[0];
    uint32_t t6 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[7] +
            (uint64_t)a[1] * b[6] +
            (uint64_t)a[2] * b[5] +
            (uint64_t)a[3] * b[4] +
            (uint64_t)a[4] * b[3] +
            (uint64_t)a[5] * b[2] +
            (uint64_t)a[6] * b[1] +
            (uint64_t)a[7] * b[0];
    uint32_t t7 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[8] +
            (uint64_t)a[1] * b[7] +
            (uint64_t)a[2] * b[6] +
            (uint64_t)a[3] * b[5] +
            (uint64_t)a[4] * b[4] +
            (uint64_t)a[5] * b[3] +
            (uint64_t)a[6] * b[2] +
            (uint64_t)a[7] * b[1] +
            (uint64_t)a[8] * b[0];
    uint32_t t8 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[0] * b[9] +
            (uint64_t)a[1] * b[8] +
            (uint64_t)a[2] * b[7] +
            (uint64_t)a[3] * b[6] +
            (uint64_t)a[4] * b[5] +
            (uint64_t)a[5] * b[4] +
            (uint64_t)a[6] * b[3] +
            (uint64_t)a[7] * b[2] +
            (uint64_t)a[8] * b[1] +
            (uint64_t)a[9] * b[0];
    uint32_t t9 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[1] * b[9] +
            (uint64_t)a[2] * b[8] +
            (uint64_t)a[3] * b[7] +
            (uint64_t)a[4] * b[6] +
            (uint64_t)a[5] * b[5] +
            (uint64_t)a[6] * b[4] +
            (uint64_t)a[7] * b[3] +
            (uint64_t)a[8] * b[2] +
            (uint64_t)a[9] * b[1];
    uint32_t t10 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[2] * b[9] +
            (uint64_t)a[3] * b[8] +
            (uint64_t)a[4] * b[7] +
            (uint64_t)a[5] * b[6] +
            (uint64_t)a[6] * b[5] +
            (uint64_t)a[7] * b[4] +
            (uint64_t)a[8] * b[3] +
            (uint64_t)a[9] * b[2];
    uint32_t t11 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[3] * b[9] +
            (uint64_t)a[4] * b[8] +
            (uint64_t)a[5] * b[7] +
            (uint64_t)a[6] * b[6] +
            (uint64_t)a[7] * b[5] +
            (uint64_t)a[8] * b[4] +
            (uint64_t)a[9] * b[3];
    uint32_t t12 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[4] * b[9] +
            (uint64_t)a[5] * b[8] +
            (uint64_t)a[6] * b[7] +
            (uint64_t)a[7] * b[6] +
            (uint64_t)a[8] * b[5] +
            (uint64_t)a[9] * b[4];
    uint32_t t13 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[5] * b[9] +
            (uint64_t)a[6] * b[8] +
            (uint64_t)a[7] * b[7] +
            (uint64_t)a[8] * b[6] +
            (uint64_t)a[9] * b[5];
    uint32_t t14 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[6] * b[9] +
            (uint64_t)a[7] * b[8] +
            (uint64_t)a[8] * b[7] +
            (uint64_t)a[9] * b[6];
    uint32_t t15 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[7] * b[9] +
            (uint64_t)a[8] * b[8] +
            (uint64_t)a[9] * b[7];
    uint32_t t16 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[8] * b[9] +
            (uint64_t)a[9] * b[8];
    uint32_t t17 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[9] * b[9];
    uint32_t t18 = c & 0x3FFFFFFUL; c = c >> 26;
    uint32_t t19 = c;

    c = t0 + (uint64_t)t10 * 0x3D10UL;
    t0 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t1 + (uint64_t)t10*0x400UL + (uint64_t)t11 * 0x3D10UL;
    t1 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t2 + (uint64_t)t11*0x400UL + (uint64_t)t12 * 0x3D10UL;
    t2 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t3 + (uint64_t)t12*0x400UL + (uint64_t)t13 * 0x3D10UL;
    r[3] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t4 + (uint64_t)t13*0x400UL + (uint64_t)t14 * 0x3D10UL;
    r[4] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t5 + (uint64_t)t14*0x400UL + (uint64_t)t15 * 0x3D10UL;
    r[5] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t6 + (uint64_t)t15*0x400UL + (uint64_t)t16 * 0x3D10UL;
    r[6] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t7 + (uint64_t)t16*0x400UL + (uint64_t)t17 * 0x3D10UL;
    r[7] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t8 + (uint64_t)t17*0x400UL + (uint64_t)t18 * 0x3D10UL;
    r[8] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t9 + (uint64_t)t18*0x400UL + (uint64_t)t19 * 0x1000003D10UL;
    r[9] = c & 0x03FFFFFUL; c = c >> 22;
    uint64_t d = t0 + c * 0x3D1UL;
    r[0] = d & 0x3FFFFFFUL; d = d >> 26;
    d = d + t1 + c*0x40;
    r[1] = d & 0x3FFFFFFUL; d = d >> 26;
    r[2] = t2 + d;
}

__device__ void secp256k1_fe_sqr_inner(const uint32_t *a, uint32_t *r) {
    uint64_t c = (uint64_t)a[0] * a[0];
    uint32_t t0 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[1];
    uint32_t t1 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[2] +
            (uint64_t)a[1] * a[1];
    uint32_t t2 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[3] +
            (uint64_t)(a[1]*2) * a[2];
    uint32_t t3 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[4] +
            (uint64_t)(a[1]*2) * a[3] +
            (uint64_t)a[2] * a[2];
    uint32_t t4 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[5] +
            (uint64_t)(a[1]*2) * a[4] +
            (uint64_t)(a[2]*2) * a[3];
    uint32_t t5 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[6] +
            (uint64_t)(a[1]*2) * a[5] +
            (uint64_t)(a[2]*2) * a[4] +
            (uint64_t)a[3] * a[3];
    uint32_t t6 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[7] +
            (uint64_t)(a[1]*2) * a[6] +
            (uint64_t)(a[2]*2) * a[5] +
            (uint64_t)(a[3]*2) * a[4];
    uint32_t t7 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[8] +
            (uint64_t)(a[1]*2) * a[7] +
            (uint64_t)(a[2]*2) * a[6] +
            (uint64_t)(a[3]*2) * a[5] +
            (uint64_t)a[4] * a[4];
    uint32_t t8 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[0]*2) * a[9] +
            (uint64_t)(a[1]*2) * a[8] +
            (uint64_t)(a[2]*2) * a[7] +
            (uint64_t)(a[3]*2) * a[6] +
            (uint64_t)(a[4]*2) * a[5];
    uint32_t t9 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[1]*2) * a[9] +
            (uint64_t)(a[2]*2) * a[8] +
            (uint64_t)(a[3]*2) * a[7] +
            (uint64_t)(a[4]*2) * a[6] +
            (uint64_t)a[5] * a[5];
    uint32_t t10 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[2]*2) * a[9] +
            (uint64_t)(a[3]*2) * a[8] +
            (uint64_t)(a[4]*2) * a[7] +
            (uint64_t)(a[5]*2) * a[6];
    uint32_t t11 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[3]*2) * a[9] +
            (uint64_t)(a[4]*2) * a[8] +
            (uint64_t)(a[5]*2) * a[7] +
            (uint64_t)a[6] * a[6];
    uint32_t t12 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[4]*2) * a[9] +
            (uint64_t)(a[5]*2) * a[8] +
            (uint64_t)(a[6]*2) * a[7];
    uint32_t t13 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[5]*2) * a[9] +
            (uint64_t)(a[6]*2) * a[8] +
            (uint64_t)a[7] * a[7];
    uint32_t t14 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[6]*2) * a[9] +
            (uint64_t)(a[7]*2) * a[8];
    uint32_t t15 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[7]*2) * a[9] +
            (uint64_t)a[8] * a[8];
    uint32_t t16 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)(a[8]*2) * a[9];
    uint32_t t17 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + (uint64_t)a[9] * a[9];
    uint32_t t18 = c & 0x3FFFFFFUL; c = c >> 26;
    uint32_t t19 = c;

    c = t0 + (uint64_t)t10 * 0x3D10UL;
    t0 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t1 + (uint64_t)t10*0x400UL + (uint64_t)t11 * 0x3D10UL;
    t1 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t2 + (uint64_t)t11*0x400UL + (uint64_t)t12 * 0x3D10UL;
    t2 = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t3 + (uint64_t)t12*0x400UL + (uint64_t)t13 * 0x3D10UL;
    r[3] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t4 + (uint64_t)t13*0x400UL + (uint64_t)t14 * 0x3D10UL;
    r[4] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t5 + (uint64_t)t14*0x400UL + (uint64_t)t15 * 0x3D10UL;
    r[5] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t6 + (uint64_t)t15*0x400UL + (uint64_t)t16 * 0x3D10UL;
    r[6] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t7 + (uint64_t)t16*0x400UL + (uint64_t)t17 * 0x3D10UL;
    r[7] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t8 + (uint64_t)t17*0x400UL + (uint64_t)t18 * 0x3D10UL;
    r[8] = c & 0x3FFFFFFUL; c = c >> 26;
    c = c + t9 + (uint64_t)t18*0x400UL + (uint64_t)t19 * 0x1000003D10UL;
    r[9] = c & 0x03FFFFFUL; c = c >> 22;
    uint64_t d = t0 + c * 0x3D1UL;
    r[0] = d & 0x3FFFFFFUL; d = d >> 26;
    d = d + t1 + c*0x40;
    r[1] = d & 0x3FFFFFFUL; d = d >> 26;
    r[2] = t2 + d;
}


__device__ void secp256k1_fe_mul(secp256k1_fe_t *r, const secp256k1_fe_t *a, const secp256k1_fe_t *b) {
#ifdef VERIFY
    assert(a->magnitude <= 8);
    assert(b->magnitude <= 8);
    r->magnitude = 1;
    r->normalized = 0;
#endif
    secp256k1_fe_mul_inner(a->n, b->n, r->n);
}

__device__ void secp256k1_fe_sqr(secp256k1_fe_t *r, const secp256k1_fe_t *a) {
#ifdef VERIFY
    assert(a->magnitude <= 8);
    r->magnitude = 1;
    r->normalized = 0;
#endif
    secp256k1_fe_sqr_inner(a->n, r->n);
}

__device__ void secp256k1_gej_double(secp256k1_gej_t *r, const secp256k1_gej_t *a) {
    secp256k1_fe_t t5 = a->y;
    secp256k1_fe_normalize(&t5);
    if (a->infinity || secp256k1_fe_is_zero(&t5)) {
        r->infinity = 1;
        return;
    }

    secp256k1_fe_t t1,t2,t3,t4;
    secp256k1_fe_mul(&r->z, &t5, &a->z);
    secp256k1_fe_mul_int(&r->z, 2);       // Z' = 2*Y*Z (2)
    secp256k1_fe_sqr(&t1, &a->x);
    secp256k1_fe_mul_int(&t1, 3);         // T1 = 3*X^2 (3)
    secp256k1_fe_sqr(&t2, &t1);           // T2 = 9*X^4 (1)
    secp256k1_fe_sqr(&t3, &t5);
    secp256k1_fe_mul_int(&t3, 2);         // T3 = 2*Y^2 (2)
    secp256k1_fe_sqr(&t4, &t3);
    secp256k1_fe_mul_int(&t4, 2);         // T4 = 8*Y^4 (2)
    secp256k1_fe_mul(&t3, &a->x, &t3);    // T3 = 2*X*Y^2 (1)
    r->x = t3;
    secp256k1_fe_mul_int(&r->x, 4);       // X' = 8*X*Y^2 (4)
    secp256k1_fe_negate(&r->x, &r->x, 4); // X' = -8*X*Y^2 (5)
    secp256k1_fe_add(&r->x, &t2);         // X' = 9*X^4 - 8*X*Y^2 (6)
    secp256k1_fe_negate(&t2, &t2, 1);     // T2 = -9*X^4 (2)
    secp256k1_fe_mul_int(&t3, 6);         // T3 = 12*X*Y^2 (6)
    secp256k1_fe_add(&t3, &t2);           // T3 = 12*X*Y^2 - 9*X^4 (8)
    secp256k1_fe_mul(&r->y, &t1, &t3);    // Y' = 36*X^3*Y^2 - 27*X^6 (1)
    secp256k1_fe_negate(&t2, &t4, 2);     // T2 = -8*Y^4 (3)
    secp256k1_fe_add(&r->y, &t2);         // Y' = 36*X^3*Y^2 - 27*X^6 - 8*Y^4 (4)
    r->infinity = 0;
}

__device__ void secp256k1_gej_add( secp256k1_gej_t *pr, const secp256k1_gej_t *pa,  const secp256k1_gej_t *pb) {
    secp256k1_gej_t b, r;
    b = *pb;
    secp256k1_gej_add_local(&r, pa, &b);
    *pr = r;
}

__device__ void secp256k1_gej_add_local(secp256k1_gej_t *pr, const secp256k1_gej_t *pa, const secp256k1_gej_t *pb) {
    if (pa->infinity) {
        *pr = *pb;
        return;
    }
    if (pb->infinity) {
        *pr = *pa;
        return;
    }
    
    secp256k1_gej_t a = *pa;
    secp256k1_gej_t b = *pb;
    secp256k1_gej_t r;
    
    r.infinity = 0;
    secp256k1_fe_t z22; secp256k1_fe_sqr(&z22, &b.z);
    secp256k1_fe_t z12; secp256k1_fe_sqr(&z12, &a.z);
    secp256k1_fe_t u1; secp256k1_fe_mul(&u1, &a.x, &z22);
    secp256k1_fe_t u2; secp256k1_fe_mul(&u2, &b.x, &z12);
    secp256k1_fe_t s1; secp256k1_fe_mul(&s1, &a.y, &z22); secp256k1_fe_mul(&s1, &s1, &b.z);
    secp256k1_fe_t s2; secp256k1_fe_mul(&s2, &b.y, &z12); secp256k1_fe_mul(&s2, &s2, &a.z);
    secp256k1_fe_normalize(&u1);
    secp256k1_fe_normalize(&u2);
    if (secp256k1_fe_equal(&u1, &u2)) {
        secp256k1_fe_normalize(&s1);
        secp256k1_fe_normalize(&s2);
        if (secp256k1_fe_equal(&s1, &s2)) {
            secp256k1_gej_double(&r, &a);
        } else {
            r.infinity = 1;
        }
        return;
    }
    secp256k1_fe_t h; secp256k1_fe_negate(&h, &u1, 1); secp256k1_fe_add(&h, &u2);
    secp256k1_fe_t i; secp256k1_fe_negate(&i, &s1, 1); secp256k1_fe_add(&i, &s2);
    secp256k1_fe_t i2; secp256k1_fe_sqr(&i2, &i);
    secp256k1_fe_t h2; secp256k1_fe_sqr(&h2, &h);
    secp256k1_fe_t h3; secp256k1_fe_mul(&h3, &h, &h2);
    secp256k1_fe_mul(&r.z, &a.z, &b.z); secp256k1_fe_mul(&r.z, &r.z, &h);
    secp256k1_fe_t t; secp256k1_fe_mul(&t, &u1, &h2);
    r.x = t; secp256k1_fe_mul_int(&r.x, 2); secp256k1_fe_add(&r.x, &h3); secp256k1_fe_negate(&r.x, &r.x, 3); secp256k1_fe_add(&r.x, &i2);
    secp256k1_fe_negate(&r.y, &r.x, 5); secp256k1_fe_add(&r.y, &t); secp256k1_fe_mul(&r.y, &r.y, &i);
    secp256k1_fe_mul(&h3, &h3, &s1); secp256k1_fe_negate(&h3, &h3, 1);
    secp256k1_fe_add(&r.y, &h3);
    
    *pr = r;
    }


__device__ void secp256k1_gej_add_ge(secp256k1_gej_t *r, const secp256k1_gej_t *a, const secp256k1_ge_t *b) {
    if (a->infinity) {
        r->infinity = b->infinity;
        r->x = b->x;
        r->y = b->y;
        secp256k1_fe_set_int(&r->z, 1);
        return;
    }
    if (b->infinity) {
        *r = *a;
        return;
    }
    r->infinity = 0;
    secp256k1_fe_t z12; secp256k1_fe_sqr(&z12, &a->z);
    secp256k1_fe_t u1 = a->x; secp256k1_fe_normalize(&u1);
    secp256k1_fe_t u2; secp256k1_fe_mul(&u2, &b->x, &z12);
    secp256k1_fe_t s1 = a->y; secp256k1_fe_normalize(&s1);
    secp256k1_fe_t s2; secp256k1_fe_mul(&s2, &b->y, &z12); secp256k1_fe_mul(&s2, &s2, &a->z);
    secp256k1_fe_normalize(&u1);
    secp256k1_fe_normalize(&u2);
    if (secp256k1_fe_equal(&u1, &u2)) {
        secp256k1_fe_normalize(&s1);
        secp256k1_fe_normalize(&s2);
        if (secp256k1_fe_equal(&s1, &s2)) {
            secp256k1_gej_double(r, a);
        } else {
            r->infinity = 1;
        }
        return;
    }
    secp256k1_fe_t h; secp256k1_fe_negate(&h, &u1, 1); secp256k1_fe_add(&h, &u2);
    secp256k1_fe_t i; secp256k1_fe_negate(&i, &s1, 1); secp256k1_fe_add(&i, &s2);
    secp256k1_fe_t i2; secp256k1_fe_sqr(&i2, &i);
    secp256k1_fe_t h2; secp256k1_fe_sqr(&h2, &h);
    secp256k1_fe_t h3; secp256k1_fe_mul(&h3, &h, &h2);
    r->z = a->z; secp256k1_fe_mul(&r->z, &r->z, &h);
    secp256k1_fe_t t; secp256k1_fe_mul(&t, &u1, &h2);
    r->x = t; secp256k1_fe_mul_int(&r->x, 2); secp256k1_fe_add(&r->x, &h3); secp256k1_fe_negate(&r->x, &r->x, 3); secp256k1_fe_add(&r->x, &i2);
    secp256k1_fe_negate(&r->y, &r->x, 5); secp256k1_fe_add(&r->y, &t); secp256k1_fe_mul(&r->y, &r->y, &i);
    secp256k1_fe_mul(&h3, &h3, &s1); secp256k1_fe_negate(&h3, &h3, 1);
    secp256k1_fe_add(&r->y, &h3);
}

__device__ void secp256k1_gej_get_x(secp256k1_fe_t *r, const secp256k1_gej_t *a) {
    secp256k1_fe_t zi2; secp256k1_fe_inv_var(&zi2, &a->z); secp256k1_fe_sqr(&zi2, &zi2);
    secp256k1_fe_mul(r, &a->x, &zi2);
}

__device__ void secp256k1_fe_inv(secp256k1_fe_t *r, const secp256k1_fe_t *a) {

    // The binary representation of (p - 2) has 5 blocks of 1s, with lengths in
    // { 1, 2, 22, 223 }. Use an addition chain to calculate 2^n - 1 for each block:
    // [1], [2], 3, 6, 9, 11, [22], 44, 88, 176, 220, [223]

    secp256k1_fe_t x2;
    secp256k1_fe_sqr(&x2, a);
    secp256k1_fe_mul(&x2, &x2, a);

    secp256k1_fe_t x3;
    secp256k1_fe_sqr(&x3, &x2);
    secp256k1_fe_mul(&x3, &x3, a);

    secp256k1_fe_t x6 = x3;
    for (int j=0; j<3; j++) secp256k1_fe_sqr(&x6, &x6);
    secp256k1_fe_mul(&x6, &x6, &x3);

    secp256k1_fe_t x9 = x6;
    for (int j=0; j<3; j++) secp256k1_fe_sqr(&x9, &x9);
    secp256k1_fe_mul(&x9, &x9, &x3);

    secp256k1_fe_t x11 = x9;
    for (int j=0; j<2; j++) secp256k1_fe_sqr(&x11, &x11);
    secp256k1_fe_mul(&x11, &x11, &x2);

    secp256k1_fe_t x22 = x11;
    for (int j=0; j<11; j++) secp256k1_fe_sqr(&x22, &x22);
    secp256k1_fe_mul(&x22, &x22, &x11);

    secp256k1_fe_t x44 = x22;
    for (int j=0; j<22; j++) secp256k1_fe_sqr(&x44, &x44);
    secp256k1_fe_mul(&x44, &x44, &x22);

    secp256k1_fe_t x88 = x44;
    for (int j=0; j<44; j++) secp256k1_fe_sqr(&x88, &x88);
    secp256k1_fe_mul(&x88, &x88, &x44);

    secp256k1_fe_t x176 = x88;
    for (int j=0; j<88; j++) secp256k1_fe_sqr(&x176, &x176);
    secp256k1_fe_mul(&x176, &x176, &x88);

    secp256k1_fe_t x220 = x176;
    for (int j=0; j<44; j++) secp256k1_fe_sqr(&x220, &x220);
    secp256k1_fe_mul(&x220, &x220, &x44);

    secp256k1_fe_t x223 = x220;
    for (int j=0; j<3; j++) secp256k1_fe_sqr(&x223, &x223);
    secp256k1_fe_mul(&x223, &x223, &x3);

    // The final result is then assembled using a sliding window over the blocks.

    secp256k1_fe_t t1 = x223;
    for (int j=0; j<23; j++) secp256k1_fe_sqr(&t1, &t1);
    secp256k1_fe_mul(&t1, &t1, &x22);
    for (int j=0; j<5; j++) secp256k1_fe_sqr(&t1, &t1);
    secp256k1_fe_mul(&t1, &t1, a);
    for (int j=0; j<3; j++) secp256k1_fe_sqr(&t1, &t1);
    secp256k1_fe_mul(&t1, &t1, &x2);
    for (int j=0; j<2; j++) secp256k1_fe_sqr(&t1, &t1);
    secp256k1_fe_mul(r, &t1, a);
}

__device__ void secp256k1_fe_inv_var(secp256k1_fe_t *r, const secp256k1_fe_t *a) {
    secp256k1_fe_inv(r, a);
}


    
