    0, 0, 0, 1, 0x45512319UL, 0x50B75FC4UL, 0x402DA172UL, 0x2FC9BAEEUL
);

static __constant__ secp256k1_feX secp256k1_ecdsa_const_order_as_feX = SECP256K1_FE_CONST(
