__device__ int secp256k1_scalar_check_overflowX(secp256k1_scalarX *a) {
    int yes = 0;
	int no = 0;
	no |= (a->d[7] < SECP256K1_N_7); /* No need for a > check. */
	no |= (a->d[6] < SECP256K1_N_6); /* No need for a > check. */
	no |= (a->d[5] < SECP256K1_N_5); /* No need for a > check. */
	no |= (a->d[4] < SECP256K1_N_4);
	yes |= (a->d[4] > SECP256K1_N_4) & ~no;
	no |= (a->d[3] < SECP256K1_N_3) & ~yes;
	yes |= (a->d[3] > SECP256K1_N_3) & ~no;
	no |= (a->d[2] < SECP256K1_N_2) & ~yes;
	yes |= (a->d[2] > SECP256K1_N_2) & ~no;
	no |= (a->d[1] < SECP256K1_N_1) & ~yes;
	yes |= (a->d[1] > SECP256K1_N_1) & ~no;
	yes |= (a->d[0] >= SECP256K1_N_0) & ~no;
	return yes;
}

__device__ int secp256k1_scalar_reduceX(secp256k1_scalarX *r, unsigned int overflow) {
    uint64_t t;
	VERIFY_CHECK(overflow <= 1);
	t = (uint64_t)r->d[0] + overflow * SECP256K1_N_C_0;
	r->d[0] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[1] + overflow * SECP256K1_N_C_1;
	r->d[1] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[2] + overflow * SECP256K1_N_C_2;
	r->d[2] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[3] + overflow * SECP256K1_N_C_3;
	r->d[3] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[4] + overflow * SECP256K1_N_C_4;
	r->d[4] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[5];
	r->d[5] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[6];
	r->d[6] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)r->d[7];
	r->d[7] = t & 0xFFFFFFFFUL;
	return overflow;
}

__device__ static void secp256k1_scalar_set_b32X(secp256k1_scalarX *r, const unsigned char *b32, int *overflow) {
    int over;
	r->d[0] = (uint32_t)b32[31] | (uint32_t)b32[30] << 8 | (uint32_t)b32[29] << 16 | (uint32_t)b32[28] << 24;
	r->d[1] = (uint32_t)b32[27] | (uint32_t)b32[26] << 8 | (uint32_t)b32[25] << 16 | (uint32_t)b32[24] << 24;
	r->d[2] = (uint32_t)b32[23] | (uint32_t)b32[22] << 8 | (uint32_t)b32[21] << 16 | (uint32_t)b32[20] << 24;
	r->d[3] = (uint32_t)b32[19] | (uint32_t)b32[18] << 8 | (uint32_t)b32[17] << 16 | (uint32_t)b32[16] << 24;
	r->d[4] = (uint32_t)b32[15] | (uint32_t)b32[14] << 8 | (uint32_t)b32[13] << 16 | (uint32_t)b32[12] << 24;
	r->d[5] = (uint32_t)b32[11] | (uint32_t)b32[10] << 8 | (uint32_t)b32[9] << 16 | (uint32_t)b32[8] << 24;
	r->d[6] = (uint32_t)b32[7] | (uint32_t)b32[6] << 8 | (uint32_t)b32[5] << 16 | (uint32_t)b32[4] << 24;
	r->d[7] = (uint32_t)b32[3] | (uint32_t)b32[2] << 8 | (uint32_t)b32[1] << 16 | (uint32_t)b32[0] << 24;
	over = secp256k1_scalar_reduceX(r, secp256k1_scalar_check_overflowX(r));
	if (overflow) {
		*overflow = over;
	}
}

int memcmpX(unsigned char *s1, unsigned char *s2, int len)
{
	int i = 0;
	for(i=0; i < len; i++)
	{
		if(s1[i] == s2[i]) {
			continue;
		}
		if(s1[i] > s2[i])
			return 1;
		if(s1[i] < s2[i])
			return -1;
	}
	return 0;
}

__device__ void memcpyX(void *dest,  const void *src, size_t len)
{
  char *d = (char*)dest;
   const char *s = (const char*)src;
  while (len--)
    *d++ = *s++;
}

__device__ void memcpy_to_global( void *dest, const void *src, size_t len)
{
   char *d = (char*)dest;
  const char *s = (const char*)src;
  while (len--)
    *d++ = *s++;
}

__device__ void private_memcpy(void *dest, const void *src, size_t len)
{
	char *d = (char*)dest;
  	const char *s = (const char*)src;
  	while (len--)
    	*d++ = *s++;
}

__device__ static void secp256k1_fe_verifyX(const secp256k1_feX *a) {
    const uint32_t *d = a->n;
    int m = a->normalized ? 1 : 2 * a->magnitude, r = 1;
    r &= (d[0] <= 0x3FFFFFFUL * m);
    r &= (d[1] <= 0x3FFFFFFUL * m);
    r &= (d[2] <= 0x3FFFFFFUL * m);
    r &= (d[3] <= 0x3FFFFFFUL * m);
    r &= (d[4] <= 0x3FFFFFFUL * m);
    r &= (d[5] <= 0x3FFFFFFUL * m);
    r &= (d[6] <= 0x3FFFFFFUL * m);
    r &= (d[7] <= 0x3FFFFFFUL * m);
    r &= (d[8] <= 0x3FFFFFFUL * m);
    r &= (d[9] <= 0x03FFFFFUL * m);
    r &= (a->magnitude >= 0);
    r &= (a->magnitude <= 32);
    if (a->normalized) {
        r &= (a->magnitude <= 1);
        if (r && (d[9] == 0x03FFFFFUL)) {
            uint32_t mid = d[8] & d[7] & d[6] & d[5] & d[4] & d[3] & d[2];
            if (mid == 0x3FFFFFFUL) {
                r &= ((d[1] + 0x40UL + ((d[0] + 0x3D1UL) >> 26)) <= 0x3FFFFFFUL);
            }
        }
    }
    VERIFY_CHECK(r == 1);
}

int secp256k1_scalar_is_zeroX(const secp256k1_scalarX *a) {
    return (a->d[0] | a->d[1] | a->d[2] | a->d[3] | a->d[4] | a->d[5] | a->d[6] | a->d[7]) == 0;
}

__device__ void secp256k1_scalar_sqr_512X(uint32_t *l, const secp256k1_scalarX *a) {
    /* 96 bit accumulator. */
	uint32_t c0 = 0, c1 = 0, c2 = 0;

	/* l[0..15] = a[0..7]^2. */
	muladd_fast(a->d[0], a->d[0]);
	extract_fast(l[0]);
	muladd2(a->d[0], a->d[1]);
	extract(l[1]);
	muladd2(a->d[0], a->d[2]);
	muladd(a->d[1], a->d[1]);
	extract(l[2]);
	muladd2(a->d[0], a->d[3]);
	muladd2(a->d[1], a->d[2]);
	extract(l[3]);
	muladd2(a->d[0], a->d[4]);
	muladd2(a->d[1], a->d[3]);
	muladd(a->d[2], a->d[2]);
	extract(l[4]);
	muladd2(a->d[0], a->d[5]);
	muladd2(a->d[1], a->d[4]);
	muladd2(a->d[2], a->d[3]);
	extract(l[5]);
	muladd2(a->d[0], a->d[6]);
	muladd2(a->d[1], a->d[5]);
	muladd2(a->d[2], a->d[4]);
	muladd(a->d[3], a->d[3]);
	extract(l[6]);
	muladd2(a->d[0], a->d[7]);
	muladd2(a->d[1], a->d[6]);
	muladd2(a->d[2], a->d[5]);
	muladd2(a->d[3], a->d[4]);
	extract(l[7]);
	muladd2(a->d[1], a->d[7]);
	muladd2(a->d[2], a->d[6]);
	muladd2(a->d[3], a->d[5]);
	muladd(a->d[4], a->d[4]);
	extract(l[8]);
	muladd2(a->d[2], a->d[7]);
	muladd2(a->d[3], a->d[6]);
	muladd2(a->d[4], a->d[5]);
	extract(l[9]);
	muladd2(a->d[3], a->d[7]);
	muladd2(a->d[4], a->d[6]);
	muladd(a->d[5], a->d[5]);
	extract(l[10]);
	muladd2(a->d[4], a->d[7]);
	muladd2(a->d[5], a->d[6]);
	extract(l[11]);
	muladd2(a->d[5], a->d[7]);
	muladd(a->d[6], a->d[6]);
	extract(l[12]);
	muladd2(a->d[6], a->d[7]);
	extract(l[13]);
	muladd_fast(a->d[7], a->d[7]);
	extract_fast(l[14]);
	VERIFY_CHECK(c1 == 0);
	l[15] = c0;
}

__device__ static void secp256k1_scalar_reduce_512X(secp256k1_scalarX *r, const uint32_t *l) {
    uint64_t c;
	uint32_t n0 = l[8], n1 = l[9], n2 = l[10], n3 = l[11], n4 = l[12], n5 = l[13], n6 = l[14], n7 = l[15];
	uint32_t m0, m1, m2, m3, m4, m5, m6, m7, m8, m9, m10, m11, m12;
	uint32_t p0, p1, p2, p3, p4, p5, p6, p7, p8;

	/* 96 bit accumulator. */
	uint32_t c0, c1, c2;

	/* Reduce 512 bits into 385. */
	/* m[0..12] = l[0..7] + n[0..7] * SECP256K1_N_C. */
	c0 = l[0]; c1 = 0; c2 = 0;
	muladd_fast(n0, SECP256K1_N_C_0);
	extract_fast(m0);
	sumadd_fast(l[1]);
	muladd(n1, SECP256K1_N_C_0);
	muladd(n0, SECP256K1_N_C_1);
	extract(m1);
	sumadd(l[2]);
	muladd(n2, SECP256K1_N_C_0);
	muladd(n1, SECP256K1_N_C_1);
	muladd(n0, SECP256K1_N_C_2);
	extract(m2);
	sumadd(l[3]);
	muladd(n3, SECP256K1_N_C_0);
	muladd(n2, SECP256K1_N_C_1);
	muladd(n1, SECP256K1_N_C_2);
	muladd(n0, SECP256K1_N_C_3);
	extract(m3);
	sumadd(l[4]);
	muladd(n4, SECP256K1_N_C_0);
	muladd(n3, SECP256K1_N_C_1);
	muladd(n2, SECP256K1_N_C_2);
	muladd(n1, SECP256K1_N_C_3);
	sumadd(n0);
	extract(m4);
	sumadd(l[5]);
	muladd(n5, SECP256K1_N_C_0);
	muladd(n4, SECP256K1_N_C_1);
	muladd(n3, SECP256K1_N_C_2);
	muladd(n2, SECP256K1_N_C_3);
	sumadd(n1);
	extract(m5);
	sumadd(l[6]);
	muladd(n6, SECP256K1_N_C_0);
	muladd(n5, SECP256K1_N_C_1);
	muladd(n4, SECP256K1_N_C_2);
	muladd(n3, SECP256K1_N_C_3);
	sumadd(n2);
	extract(m6);
	sumadd(l[7]);
	muladd(n7, SECP256K1_N_C_0);
	muladd(n6, SECP256K1_N_C_1);
	muladd(n5, SECP256K1_N_C_2);
	muladd(n4, SECP256K1_N_C_3);
	sumadd(n3);
	extract(m7);
	muladd(n7, SECP256K1_N_C_1);
	muladd(n6, SECP256K1_N_C_2);
	muladd(n5, SECP256K1_N_C_3);
	sumadd(n4);
	extract(m8);
	muladd(n7, SECP256K1_N_C_2);
	muladd(n6, SECP256K1_N_C_3);
	sumadd(n5);
	extract(m9);
	muladd(n7, SECP256K1_N_C_3);
	sumadd(n6);
	extract(m10);
	sumadd_fast(n7);
	extract_fast(m11);
	VERIFY_CHECK(c0 <= 1);
	m12 = c0;

	/* Reduce 385 bits into 258. */
	/* p[0..8] = m[0..7] + m[8..12] * SECP256K1_N_C. */
	c0 = m0; c1 = 0; c2 = 0;
	muladd_fast(m8, SECP256K1_N_C_0);
	extract_fast(p0);
	sumadd_fast(m1);
	muladd(m9, SECP256K1_N_C_0);
	muladd(m8, SECP256K1_N_C_1);
	extract(p1);
	sumadd(m2);
	muladd(m10, SECP256K1_N_C_0);
	muladd(m9, SECP256K1_N_C_1);
	muladd(m8, SECP256K1_N_C_2);
	extract(p2);
	sumadd(m3);
	muladd(m11, SECP256K1_N_C_0);
	muladd(m10, SECP256K1_N_C_1);
	muladd(m9, SECP256K1_N_C_2);
	muladd(m8, SECP256K1_N_C_3);
	extract(p3);
	sumadd(m4);
	muladd(m12, SECP256K1_N_C_0);
	muladd(m11, SECP256K1_N_C_1);
	muladd(m10, SECP256K1_N_C_2);
	muladd(m9, SECP256K1_N_C_3);
	sumadd(m8);
	extract(p4);
	sumadd(m5);
	muladd(m12, SECP256K1_N_C_1);
	muladd(m11, SECP256K1_N_C_2);
	muladd(m10, SECP256K1_N_C_3);
	sumadd(m9);
	extract(p5);
	sumadd(m6);
	muladd(m12, SECP256K1_N_C_2);
	muladd(m11, SECP256K1_N_C_3);
	sumadd(m10);
	extract(p6);
	sumadd_fast(m7);
	muladd_fast(m12, SECP256K1_N_C_3);
	sumadd_fast(m11);
	extract_fast(p7);
	p8 = c0 + m12;
	VERIFY_CHECK(p8 <= 2);

	/* Reduce 258 bits into 256. */
	/* r[0..7] = p[0..7] + p[8] * SECP256K1_N_C. */
	c = p0 + (uint64_t)SECP256K1_N_C_0 * p8;
	r->d[0] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p1 + (uint64_t)SECP256K1_N_C_1 * p8;
	r->d[1] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p2 + (uint64_t)SECP256K1_N_C_2 * p8;
	r->d[2] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p3 + (uint64_t)SECP256K1_N_C_3 * p8;
	r->d[3] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p4 + (uint64_t)p8;
	r->d[4] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p5;
	r->d[5] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p6;
	r->d[6] = c & 0xFFFFFFFFUL; c >>= 32;
	c += p7;
	r->d[7] = c & 0xFFFFFFFFUL; c >>= 32;

	/* Final reduction of r. */
	secp256k1_scalar_reduceX(r, c + secp256k1_scalar_check_overflowX(r));
}

__device__ void secp256k1_scalar_sqrX(secp256k1_scalarX *r, const secp256k1_scalarX *a) {
    uint32_t l[16];
	secp256k1_scalar_sqr_512X(l, a);
	secp256k1_scalar_reduce_512X(r, l);
}

__device__ static void secp256k1_scalar_mul_512X(uint32_t *l, const secp256k1_scalarX *a, const secp256k1_scalarX *b) {
    /* 96 bit accumulator. */
	uint32_t c0 = 0, c1 = 0, c2 = 0;

	/* l[0..15] = a[0..7] * b[0..7]. */
	muladd_fast(a->d[0], b->d[0]);
	extract_fast(l[0]);
	muladd(a->d[0], b->d[1]);
	muladd(a->d[1], b->d[0]);
	extract(l[1]);
	muladd(a->d[0], b->d[2]);
	muladd(a->d[1], b->d[1]);
	muladd(a->d[2], b->d[0]);
	extract(l[2]);
	muladd(a->d[0], b->d[3]);
	muladd(a->d[1], b->d[2]);
	muladd(a->d[2], b->d[1]);
	muladd(a->d[3], b->d[0]);
	extract(l[3]);
	muladd(a->d[0], b->d[4]);
	muladd(a->d[1], b->d[3]);
	muladd(a->d[2], b->d[2]);
	muladd(a->d[3], b->d[1]);
	muladd(a->d[4], b->d[0]);
	extract(l[4]);
	muladd(a->d[0], b->d[5]);
	muladd(a->d[1], b->d[4]);
	muladd(a->d[2], b->d[3]);
	muladd(a->d[3], b->d[2]);
	muladd(a->d[4], b->d[1]);
	muladd(a->d[5], b->d[0]);
	extract(l[5]);
	muladd(a->d[0], b->d[6]);
	muladd(a->d[1], b->d[5]);
	muladd(a->d[2], b->d[4]);
	muladd(a->d[3], b->d[3]);
	muladd(a->d[4], b->d[2]);
	muladd(a->d[5], b->d[1]);
	muladd(a->d[6], b->d[0]);
	extract(l[6]);
	muladd(a->d[0], b->d[7]);
	muladd(a->d[1], b->d[6]);
	muladd(a->d[2], b->d[5]);
	muladd(a->d[3], b->d[4]);
	muladd(a->d[4], b->d[3]);
	muladd(a->d[5], b->d[2]);
	muladd(a->d[6], b->d[1]);
	muladd(a->d[7], b->d[0]);
	extract(l[7]);
	muladd(a->d[1], b->d[7]);
	muladd(a->d[2], b->d[6]);
	muladd(a->d[3], b->d[5]);
	muladd(a->d[4], b->d[4]);
	muladd(a->d[5], b->d[3]);
	muladd(a->d[6], b->d[2]);
	muladd(a->d[7], b->d[1]);
	extract(l[8]);
	muladd(a->d[2], b->d[7]);
	muladd(a->d[3], b->d[6]);
	muladd(a->d[4], b->d[5]);
	muladd(a->d[5], b->d[4]);
	muladd(a->d[6], b->d[3]);
	muladd(a->d[7], b->d[2]);
	extract(l[9]);
	muladd(a->d[3], b->d[7]);
	muladd(a->d[4], b->d[6]);
	muladd(a->d[5], b->d[5]);
	muladd(a->d[6], b->d[4]);
	muladd(a->d[7], b->d[3]);
	extract(l[10]);
	muladd(a->d[4], b->d[7]);
	muladd(a->d[5], b->d[6]);
	muladd(a->d[6], b->d[5]);
	muladd(a->d[7], b->d[4]);
	extract(l[11]);
	muladd(a->d[5], b->d[7]);
	muladd(a->d[6], b->d[6]);
	muladd(a->d[7], b->d[5]);
	extract(l[12]);
	muladd(a->d[6], b->d[7]);
	muladd(a->d[7], b->d[6]);
	extract(l[13]);
	muladd_fast(a->d[7], b->d[7]);
	extract_fast(l[14]);
	VERIFY_CHECK(c1 == 0);
	l[15] = c0;
}

__device__ void secp256k1_scalar_mulX(secp256k1_scalarX *r, const secp256k1_scalarX *a, const secp256k1_scalarX *b) {
    uint32_t l[16];
	secp256k1_scalar_mul_512X(l, a, b);
	secp256k1_scalar_reduce_512X(r, l);
}

__device__ void secp256k1_scalar_inverseX(secp256k1_scalarX *r, const secp256k1_scalarX *x) {
    secp256k1_scalarX *t;
    int i;
    /* First compute x ^ (2^N - 1) for some values of N. */
    secp256k1_scalarX x2, x3, x4, x6, x7, x8, x15, x30, x60, x120, x127;

    secp256k1_scalar_sqrX(&x2,  x);
    secp256k1_scalar_mulX(&x2, &x2,  x);

    secp256k1_scalar_sqrX(&x3, &x2);
    secp256k1_scalar_mulX(&x3, &x3,  x);

    secp256k1_scalar_sqrX(&x4, &x3);
    secp256k1_scalar_mulX(&x4, &x4,  x);

    secp256k1_scalar_sqrX(&x6, &x4);
    secp256k1_scalar_sqrX(&x6, &x6);
    secp256k1_scalar_mulX(&x6, &x6, &x2);

    secp256k1_scalar_sqrX(&x7, &x6);
    secp256k1_scalar_mulX(&x7, &x7,  x);

    secp256k1_scalar_sqrX(&x8, &x7);
    secp256k1_scalar_mulX(&x8, &x8,  x);

    secp256k1_scalar_sqrX(&x15, &x8);
    for (i = 0; i < 6; i++) {
        secp256k1_scalar_sqrX(&x15, &x15);
    }
    secp256k1_scalar_mulX(&x15, &x15, &x7);

    secp256k1_scalar_sqrX(&x30, &x15);
    for (i = 0; i < 14; i++) {
        secp256k1_scalar_sqrX(&x30, &x30);
    }
    secp256k1_scalar_mulX(&x30, &x30, &x15);

    secp256k1_scalar_sqrX(&x60, &x30);
    for (i = 0; i < 29; i++) {
        secp256k1_scalar_sqrX(&x60, &x60);
    }
    secp256k1_scalar_mulX(&x60, &x60, &x30);

    secp256k1_scalar_sqrX(&x120, &x60);
    for (i = 0; i < 59; i++) {
        secp256k1_scalar_sqrX(&x120, &x120);
    }
    secp256k1_scalar_mulX(&x120, &x120, &x60);

    secp256k1_scalar_sqrX(&x127, &x120);
    for (i = 0; i < 6; i++) {
        secp256k1_scalar_sqrX(&x127, &x127);
    }
    secp256k1_scalar_mulX(&x127, &x127, &x7);

    /* Then accumulate the final result (t starts at x127). */
    t = &x127;
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 4; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 4; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 3; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 4; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 5; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 4; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 5; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x4); /* 1111 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 3; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 4; i++) { /* 000 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 10; i++) { /* 0000000 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 4; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x3); /* 111 */
    for (i = 0; i < 9; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x8); /* 11111111 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 3; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 3; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 5; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x4); /* 1111 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 5; i++) { /* 000 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 4; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 2; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 8; i++) { /* 000000 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 3; i++) { /* 0 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, &x2); /* 11 */
    for (i = 0; i < 3; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 6; i++) { /* 00000 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(t, t, x); /* 1 */
    for (i = 0; i < 8; i++) { /* 00 */
        secp256k1_scalar_sqrX(t, t);
    }
    secp256k1_scalar_mulX(r, t, &x6); /* 111111 */
}

__device__ static void secp256k1_scalar_inverse_varX(secp256k1_scalarX *r, const secp256k1_scalarX *x) {
    secp256k1_scalar_inverseX(r, x);
}

__device__ static void secp256k1_scalar_clearX(secp256k1_scalarX *r) {
    r->d[0] = 0;
	r->d[1] = 0;
	r->d[2] = 0;
	r->d[3] = 0;
	r->d[4] = 0;
	r->d[5] = 0;
	r->d[6] = 0;
	r->d[7] = 0;
}

__device__ unsigned int secp256k1_scalar_get_bitsX(const secp256k1_scalarX *a, unsigned int offset, unsigned int count) {
    VERIFY_CHECK((offset + count - 1) >> 5 == offset >> 5);
	return (a->d[offset >> 5] >> (offset & 0x1F)) & ((1 << count) - 1);
}

static void secp256k1_scalar_negateX(secp256k1_scalarX *r, const secp256k1_scalarX *a) {
    uint32_t nonzero = 0xFFFFFFFFUL * (secp256k1_scalar_is_zeroX(a) == 0);
	uint64_t t = (uint64_t)(~a->d[0]) + SECP256K1_N_0 + 1;
	r->d[0] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[1]) + SECP256K1_N_1;
	r->d[1] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[2]) + SECP256K1_N_2;
	r->d[2] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[3]) + SECP256K1_N_3;
	r->d[3] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[4]) + SECP256K1_N_4;
	r->d[4] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[5]) + SECP256K1_N_5;
	r->d[5] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[6]) + SECP256K1_N_6;
	r->d[6] = t & nonzero; t >>= 32;
	t += (uint64_t)(~a->d[7]) + SECP256K1_N_7;
	r->d[7] = t & nonzero;
}

__device__ unsigned int secp256k1_scalar_get_bits_varX(const secp256k1_scalarX *a, unsigned int offset, unsigned int count) {
    VERIFY_CHECK(count < 32);
	VERIFY_CHECK(offset + count <= 256);
	if ((offset + count - 1) >> 5 == offset >> 5) {
		return secp256k1_scalar_get_bitsX(a, offset, count);
	} else {
		VERIFY_CHECK((offset >> 5) + 1 < 8);
		return ((a->d[offset >> 5] >> (offset & 0x1F)) | (a->d[(offset >> 5) + 1] << (32 - (offset & 0x1F)))) & ((((uint32_t)1) << count) - 1);
	}
}

__device__ static void secp256k1_scalar_get_b32X(unsigned char *bin, const secp256k1_scalarX* a) {
    bin[0] = a->d[7] >> 24; bin[1] = a->d[7] >> 16; bin[2] = a->d[7] >> 8; bin[3] = a->d[7];
	bin[4] = a->d[6] >> 24; bin[5] = a->d[6] >> 16; bin[6] = a->d[6] >> 8; bin[7] = a->d[6];
	bin[8] = a->d[5] >> 24; bin[9] = a->d[5] >> 16; bin[10] = a->d[5] >> 8; bin[11] = a->d[5];
	bin[12] = a->d[4] >> 24; bin[13] = a->d[4] >> 16; bin[14] = a->d[4] >> 8; bin[15] = a->d[4];
	bin[16] = a->d[3] >> 24; bin[17] = a->d[3] >> 16; bin[18] = a->d[3] >> 8; bin[19] = a->d[3];
	bin[20] = a->d[2] >> 24; bin[21] = a->d[2] >> 16; bin[22] = a->d[2] >> 8; bin[23] = a->d[2];
	bin[24] = a->d[1] >> 24; bin[25] = a->d[1] >> 16; bin[26] = a->d[1] >> 8; bin[27] = a->d[1];
	bin[28] = a->d[0] >> 24; bin[29] = a->d[0] >> 16; bin[30] = a->d[0] >> 8; bin[31] = a->d[0];
}
__device__ static int secp256k1_scalar_addX(secp256k1_scalarX *r, const secp256k1_scalarX *a, const secp256k1_scalarX *b) {
    int overflow;
	uint64_t t = (uint64_t)a->d[0] + b->d[0];
	r->d[0] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[1] + b->d[1];
	r->d[1] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[2] + b->d[2];
	r->d[2] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[3] + b->d[3];
	r->d[3] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[4] + b->d[4];
	r->d[4] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[5] + b->d[5];
	r->d[5] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[6] + b->d[6];
	r->d[6] = t & 0xFFFFFFFFUL; t >>= 32;
	t += (uint64_t)a->d[7] + b->d[7];
	r->d[7] = t & 0xFFFFFFFFUL; t >>= 32;
	overflow = t + secp256k1_scalar_check_overflowX(r);
	VERIFY_CHECK(overflow == 0 || overflow == 1);
	secp256k1_scalar_reduceX(r, overflow);
	return overflow;
}


    
