    // === DEVICE FUNCTIONS ===
    
__device__     void secp256k1_pubkey_gen_private(const unsigned char *priv_bytes, unsigned char *pub_key) {
        secp256k1_gej_t r;
        secp256k1_gej_set_infinity(&r);
        secp256k1_ge_t p_ge;
        
        for (int w = 0; w < 64; w++) {
            int byte_idx = 31 - (w / 2);
            int nibble_shift = (w % 2) * 4;
            int val = (priv_bytes[byte_idx] >> nibble_shift) & 0xF;
            
            if (val > 0) {
                int idx = (w * 15 + (val - 1)) * 16;
                unsigned char x_bytes[32];
                unsigned char y_bytes[32];
                
                for(int j=0; j<8; j++) {
                     unsigned int w_x = precomp_g[idx + j];
                     unsigned int w_y = precomp_g[idx + 8 + j];
                     x_bytes[j*4 + 0] = (w_x >> 24) & 0xFF;
                     x_bytes[j*4 + 1] = (w_x >> 16) & 0xFF;
                     x_bytes[j*4 + 2] = (w_x >> 8) & 0xFF;
                     x_bytes[j*4 + 3] = (w_x) & 0xFF;
                     
                     y_bytes[j*4 + 0] = (w_y >> 24) & 0xFF;
                     y_bytes[j*4 + 1] = (w_y >> 16) & 0xFF;
                     y_bytes[j*4 + 2] = (w_y >> 8) & 0xFF;
                     y_bytes[j*4 + 3] = (w_y) & 0xFF;
                }
                
                secp256k1_fe_set_b32(&p_ge.x, x_bytes);
                secp256k1_fe_set_b32(&p_ge.y, y_bytes);
                p_ge.infinity = 0;
                secp256k1_gej_add_ge(&r, &r, &p_ge);
            }
        }
        
        secp256k1_fe_t zinv, zinv2, zinv3, x_aff, y_aff;
        secp256k1_fe_inv(&zinv, &r.z);
        secp256k1_fe_sqr(&zinv2, &zinv);
        secp256k1_fe_mul(&zinv3, &zinv2, &zinv);
        secp256k1_fe_mul(&x_aff, &r.x, &zinv2);
        secp256k1_fe_mul(&y_aff, &r.y, &zinv3);
        secp256k1_fe_normalize(&x_aff);
        secp256k1_fe_normalize(&y_aff);
        
        pub_key[0] = 0x02 | (secp256k1_fe_is_odd(&y_aff) ? 1 : 0);
        secp256k1_fe_get_b32(&pub_key[1], &x_aff);
    }
    
    
    // === DEVICE HELPER FUNCTIONS ===
    
    // Helper to get unsigned long long from byte array (Little Endian Load)
    // Used to feed HMAC-SHA512 which does SWAP64 internaly
__device__     unsigned long long get_ulong_le(const unsigned char *data, int offset) {
        unsigned long long val = 0;
        for(int i=0; i<8; i++) {
            val |= ((unsigned long long)data[offset + i]) << (8*i);
        }
        return val;
    }
    
    // Helper to write unsigned long long to byte array (Little Endian Write)
    // Used to read output of HMAC-SHA512 which is swapped in memory
    void put_ulong_le(unsigned char *data, int offset, unsigned long long val) {
        for(int i=0; i<8; i++) {
            data[offset + i] = (val >> (8*i)) & 0xFF;
        }
    }
    
    // Also keep Big Endian helper for other things if needed?
    // Bip32 index is BE. Scalar set_b32 expects BE bytes.
    // So we still need BE packing for those specific small parts if we manipulate bytes manually.
    // But mostly we used helpers for unsigned long long conversions.
    
    void secp256k1_scalar_get_b32_custom(unsigned char *bin, const secp256k1_scalarX *a) {
        for(int i=0; i<8; i++) {
            uint32_t limb = a->d[7-i];
            bin[i*4 + 0] = (limb >> 24) & 0xFF;
            bin[i*4 + 1] = (limb >> 16) & 0xFF;
            bin[i*4 + 2] = (limb >> 8) & 0xFF;
            bin[i*4 + 3] = (limb) & 0xFF;
        }
    }
    
__device__     void bip32_ckd_private(
        const unsigned char *parent_key, 
        const unsigned char *parent_chain, 
        unsigned int index, 
        unsigned char *out_key, 
        unsigned char *out_chain) 
    {
        unsigned char data[37];
        int data_len = 0;
        
        if (index >= 0x80000000) {
            // Hardened
            data[0] = 0x00;
            for(int i=0; i<32; i++) data[1+i] = parent_key[i];
            // Index is BE
            data[33] = (index >> 24) & 0xFF;
            data[34] = (index >> 16) & 0xFF;
            data[35] = (index >> 8) & 0xFF;
            data[36] = (index) & 0xFF;
            data_len = 37;
        } else {
            // Normal
             unsigned char pub[33];
             secp256k1_pubkey_gen_private(parent_key, pub);
             for(int i=0; i<33; i++) data[i] = pub[i];
             data[33] = (index >> 24) & 0xFF;
             data[34] = (index >> 16) & 0xFF;
             data[35] = (index >> 8) & 0xFF;
             data[36] = (index) & 0xFF;
             data_len = 37;
        }
        
        // HMAC-SHA512
        unsigned long long ipad[8], opad[8];
        unsigned long long chain_u[4]; 
        // Use LE load for HMAC input
        for(int i=0; i<4; i++) chain_u[i] = get_ulong_le(parent_chain, i*8);
        
        hmac_sha512_prepare(chain_u, 32, ipad, opad);
        
        unsigned long long data_u[5]; 
        for(int i=0; i<5; i++) data_u[i] = 0;
        for(int i=0; i<data_len; i++) {
             // LE Packing
             int u_idx = i / 8;
             int shift = (i % 8) * 8; 
             data_u[u_idx] |= ((unsigned long long)data[i] << shift);
        }
        
        unsigned long long out_512[8];
        hmac_sha512_step(ipad, opad, data_u, data_len, out_512);
        
        // IL = out_512[0..3]
        // IR = out_512[4..7] 
        // IMPORTANT: out_512 is already SWAP64'd in hmac_sha512_step (line 133)
        // So it's in Big Endian byte order in memory
        // We can read it directly as bytes
        
        // Save IR to out_chain (bytes) - direct copy
        for(int i=0; i<32; i++) {
            out_chain[i] = ((unsigned char*)(&out_512[4]))[i];
        }
        
        // Calculate ChildKey = (Parent + IL) mod n
        secp256k1_scalarX s_parent, s_il, s_child;
        int overflow;
        
        // Load Parent (bytes BE -> scalar)
        secp256k1_scalar_set_b32X(&s_parent, parent_key, &overflow);
        
        // Load IL - direct copy from out_512[0..3]
        unsigned char il_bytes[32];
        for(int i=0; i<32; i++) {
            il_bytes[i] = ((unsigned char*)out_512)[i];
        }
        
        secp256k1_scalar_set_b32X(&s_il, il_bytes, &overflow);
        
        // Add
        secp256k1_scalar_addX(&s_child, &s_parent, &s_il);
        
        // Store Child (scalar -> bytes BE)
        secp256k1_scalar_get_b32X(out_key, &s_child);
    }
    
__device__     void hmac_sha512_bytes(
        const unsigned char *key, int key_len,
        const unsigned char *data, int data_len,
        unsigned char *out_64)
    {
         unsigned long long ipad[8], opad[8];
         unsigned long long key_u[16]; 
         for(int i=0; i<16; i++) key_u[i] = 0;
         
         // Use LE Pack
         for(int i=0; i<key_len; i++) {
             int u_idx = i / 8;
             int shift = (i % 8) * 8; 
             key_u[u_idx] |= ((unsigned long long)key[i] << shift);
         }
         
         hmac_sha512_prepare(key_u, key_len, ipad, opad);
         
         unsigned long long data_u[16]; 
         for(int i=0; i<16; i++) data_u[i] = 0;
         for(int i=0; i<data_len; i++) {
             int u_idx = i / 8;
             int shift = (i % 8) * 8; 
             data_u[u_idx] |= ((unsigned long long)data[i] << shift);
         }
         
         unsigned long long out_u[8];
         hmac_sha512_step(ipad, opad, data_u, data_len, out_u);
         
         // Direct byte copy - out_u is already in BE format after SWAP64
         for(int i=0; i<64; i++) {
             out_64[i] = ((unsigned char*)out_u)[i];
         }
    }
    
    
    // === PIPELINE KERNEL ===
    
    __global__ void bip32_pipeline_bip49(
         const unsigned char *seeds, 
         unsigned char *out_hashes,
        unsigned int num_addresses,
        unsigned int num_keys) 
    {
        int gid = (blockIdx.x * blockDim.x + threadIdx.x);
        if (gid >= num_keys) return;
        unsigned char seed[64];
        for(int i=0; i<64; i++) seed[i] = seeds[gid*64 + i];
        
        unsigned char k[32];
        unsigned char c[32];
        unsigned char out_buf[64];
        
        // 1. Master Key
        // HMAC("Bitcoin seed", Seed)
        unsigned char btc_seed[] = "Bitcoin seed";
        hmac_sha512_bytes(btc_seed, 12, seed, 64, out_buf);
        for(int i=0; i<32; i++) k[i] = out_buf[i]; // Left = Key
        for(int i=0; i<32; i++) c[i] = out_buf[32+i]; // Right = Chain
        
        // 2. Derive m/49' (Hardened)
        bip32_ckd_private(k, c, 0x80000031, k, c);
        
        // 3. Derive /0' (Hardened) - Coin
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 4. Derive /0' (Hardened) - Account
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 5. Derive /0 (Normal) - External Chain
        bip32_ckd_private(k, c, 0, k, c);
        
        // 6. Loop Addresses
        for(unsigned int i=0; i<num_addresses; i++) {
             unsigned char child_k[32];
             unsigned char child_c[32]; // unused
             
             // Derive /i (Normal)
             bip32_ckd_private(k, c, i, child_k, child_c);
             
             // Pub Key
             unsigned char pub[33];
             secp256k1_pubkey_gen_private(child_k, pub);
             
             // Hash160
             unsigned char sha[32];
             sha256(pub, 33, sha);
             
             unsigned char ripe[20];
             ripemd160_32(sha, ripe);
             
             // Write to Global
             int offset = (gid * num_addresses + i) * 20;
             for(int j=0; j<20; j++) out_hashes[offset+j] = ripe[j];
        }
    }

    __global__ void bip32_pipeline_bip49_priv(
         const unsigned char *seeds, 
         unsigned char *out_privs,
        unsigned int num_addresses,
        unsigned int num_keys) 
    {
        int gid = (blockIdx.x * blockDim.x + threadIdx.x);
        if (gid >= num_keys) return;
        unsigned char seed[64];
        for(int i=0; i<64; i++) seed[i] = seeds[gid*64 + i];
        
        unsigned char k[32];
        unsigned char c[32];
        unsigned char out_buf[64];
        
        // 1. Master Key
        unsigned char btc_seed[] = "Bitcoin seed";
        hmac_sha512_bytes(btc_seed, 12, seed, 64, out_buf);
        for(int i=0; i<32; i++) k[i] = out_buf[i];
        for(int i=0; i<32; i++) c[i] = out_buf[32+i];
        
        // 2. Derive m/49' (Hardened)
        bip32_ckd_private(k, c, 0x80000031, k, c);
        
        // 3. Derive /0' (Hardened) - Coin
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 4. Derive /0' (Hardened) - Account
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 5. Derive /0 (Normal) - External Chain
        bip32_ckd_private(k, c, 0, k, c);
        
        // 6. Loop Addresses
        for(unsigned int i=0; i<num_addresses; i++) {
             unsigned char child_k[32];
             unsigned char child_c[32];
             
             // Derive /i (Normal)
             bip32_ckd_private(k, c, i, child_k, child_c);
             
             // Write Private Key to Global (32 bytes)
             int offset = (gid * num_addresses + i) * 32;
             for(int j=0; j<32; j++) out_privs[offset+j] = child_k[j];
        }
    }

