        // 2. Derive m/44' (Hardened)
        bip32_ckd_private(k, c, 0x8000002C, k, c);
        
        // 3. Derive /0' (Hardened) - Coin
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 4. Derive /0' (Hardened) - Account
        bip32_ckd_private(k, c, 0x80000000, k, c);
        
        // 5. Derive /0 (Normal) - External Chain
        bip32_ckd_private(k, c, 0, k, c);
        
